'union all',
'select h.change_date SORT_COLUMN,',
'    null EVENT_ATTRIBUTES,',
'    null EVENT_MODIFIERS,',
'    ''u-color-''|| (ora_hash(c.updated_by,44) + 1) USER_COLOR,',
